package com.grounditemsmodifiable;

import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import lombok.Builder;
import lombok.Data;
import net.runelite.api.ItemLayer;

@Data
@Builder
class GroundItem
{
	private int id;
	private int itemId;
	private String name;
	private int quantity;
	private ItemLayer itemLayer;
	private int haPrice;
	private long gePrice;
	private int offset;
	private boolean tradeable;
	private int ownership;
	private boolean isPrivate;
	private Instant spawnTime;
	private boolean stackable;
	private Duration despawnTime;
	private Duration visibleTime;
	// user-chosen name for this item id, null when not renamed
	private String displayName;

	// cached values derived from config
	boolean highlighted;
	boolean hidden;
	Color color;

	int getHaPrice()
	{
		return haPrice * quantity;
	}

	long getGePrice()
	{
		return gePrice * quantity;
	}

	String getDisplayName()
	{
		return displayName != null ? displayName : name;
	}

	boolean isRenamed()
	{
		return displayName != null && !displayName.equals(name);
	}

	void reset()
	{
		highlighted = hidden = false;
		color = null;
	}
}

