package com.grounditemsmodifiable;

import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.client.util.HotkeyListener;

class GroundItemHotkeyListener extends HotkeyListener
{
	private final GroundItemsModifiablePlugin plugin;
	private final GroundItemsModifiableConfig config;

	private Instant lastPress;

	@Inject
	private GroundItemHotkeyListener(GroundItemsModifiablePlugin plugin, GroundItemsModifiableConfig config)
	{
		super(config::hotkey);

		this.plugin = plugin;
		this.config = config;
	}

	@Override
	public void hotkeyPressed()
	{
		if (plugin.isHideAll())
		{
			plugin.setHideAll(false);
			plugin.setHotKeyPressed(true);
			lastPress = null;
		}
		else if (lastPress != null && !plugin.isHotKeyPressed() && config.doubleTapDelay() > 0 && Duration.between(lastPress, Instant.now()).compareTo(Duration.ofMillis(config.doubleTapDelay())) < 0)
		{
			plugin.setHideAll(true);
			lastPress = null;
		}
		else
		{
			plugin.setHotKeyPressed(true);
			lastPress = Instant.now();
		}
	}

	@Override
	public void hotkeyReleased()
	{
		plugin.setHotKeyPressed(false);
		plugin.setTextBoxBounds(null);
		plugin.setHiddenBoxBounds(null);
		plugin.setHighlightBoxBounds(null);
	}
}

