package com.grounditemsmodifiable;

import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.client.util.WildcardMatcher;

@Value
class ItemList
{
	static final int NONE = 0;
	static final int WILDCARD = 1;
	static final int EXACT = 2;

	List<ItemThreshold> items;

	ItemList(List<String> items)
	{
		this.items = items.stream()
			.map(ItemThreshold::fromName)
			.filter(Objects::nonNull)
			.collect(Collectors.toList());
	}

	int matches(GroundItem item)
	{
		for (ItemThreshold it : items)
		{
			if (!it.isWildcard()
				&& (it.getName().equalsIgnoreCase(item.getName()) || it.getName().equalsIgnoreCase(item.getDisplayName()))
				&& it.quantityHolds(item.getQuantity()))
			{
				return EXACT;
			}
		}

		for (ItemThreshold it : items)
		{
			if (it.isWildcard()
				&& (WildcardMatcher.matches(it.getName(), item.getName()) || WildcardMatcher.matches(it.getName(), item.getDisplayName()))
				&& it.quantityHolds(item.getQuantity()))
			{
				return WILDCARD;
			}
		}

		return NONE;
	}
}

