package com.grounditemsmodifiable.config;

import com.grounditemsmodifiable.GroundItemsModifiableConfig;

public enum HighlightTier
{
	OFF,
	LOW,
	MEDIUM,
	HIGH,
	INSANE;

	public int getValueFromTier(GroundItemsModifiableConfig config)
	{
		switch (this)
		{
			case LOW:
				return config.lowValuePrice();
			case MEDIUM:
				return config.mediumValuePrice();
			case HIGH:
				return config.highValuePrice();
			case INSANE:
				return config.insaneValuePrice();
			default:
				throw new UnsupportedOperationException();
		}
	}
}

